    /**
     * Adds a marker to the collection.
     *
     * @param {String} name Name of the marker.
     * @param {module:engine/model/range~Range} range Range of the marker.
     * @param {Boolean} [managedUsingOperations=false] Specifies whether the marker is managed using operations.
     * @param {Boolean} [affectsData=false] Specifies whether the marker affects the data produced by the data pipeline.
     * @returns {module:engine/model/markercollection~Marker} The marker instance added to the collection.
     */
    set(name, range, managedUsingOperations = false, affectsData = false) {
        if (this._markers.has(name)) {
            throw new CKEditorError('markercollection-marker-already-exists', this, { name });
        }

        const marker = new Marker(name, LiveRange.fromRange(range), managedUsingOperations, affectsData);
        this._markers.set(name, marker);
        this.fire('update', marker, null, range);

        return marker;
    }

    /**
     * Removes a marker from the collection.
     *
     * @param {String} name Name of the marker to remove.
     * @returns {Boolean} `true` if the marker was found and removed, `false` otherwise.
     */
    remove(name) {
        const marker = this._markers.get(name);
        if (!marker) {
            return false;
        }

        this._markers.delete(name);
        this.fire('update', null, marker.getRange(), null);
        marker._detachLiveRange();

        return true;
    }

    /**
     * Returns the marker with the given name.
     *
     * @param {String} name Name of the marker to get.
     * @returns {module:engine/model/markercollection~Marker|null} The marker instance or `null` if no marker with the given name exists.
     */
    get(name) {
        return this._markers.get(name) || null;
    }

    /**
     * Checks if a marker with the given name exists in the collection.
     *
     * @param {String} name Name of the marker to check.
     * @returns {Boolean} `true` if the marker exists, `false` otherwise.
     */
    has(name) {
        return this._markers.has(name);
    }

    /**
     * Returns an iterator that iterates over all markers in the collection.
     *
     * @returns {Iterable.<module:engine/model/markercollection~Marker>}
     */
    [Symbol.iterator]() {
        return this._markers.values();
    }

