    @Override
    public boolean onInterceptTouchEvent(MotionEvent ev) {
        final int action = ev.getAction();
        if (action == MotionEvent.ACTION_DOWN) {
            mDownX = (int) ev.getX();
            mDownY = (int) ev.getY();
            mPressing = true;
            mHandler.postDelayed(mLongpressCheck, ViewConfiguration.getLongPressTimeout());
        } else if (action == MotionEvent.ACTION_MOVE) {
            int deltaX = (int) ev.getX() - mDownX;
            int deltaY = (int) ev.getY() - mDownY;
            int distanceSquared = deltaX * deltaX + deltaY * deltaY;
            if (distanceSquared > mTouchSlopSquared) {
                mPressing = false;
                mHandler.removeCallbacks(mLongpressCheck);
            }
        } else if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
            mPressing = false;
            mHandler.removeCallbacks(mLongpressCheck);
            if (mInLongpress) {
                mInLongpress = false;
                return true;
            }
        }
        return super.onInterceptTouchEvent(ev);
    }

    @Override
    public boolean onTouchEvent(MotionEvent ev) {
        if (mInLongpress) {
            return true;
        }
        return super.onTouchEvent(ev);
    }

