def _remove_file(path):
        try:
            os.remove(path)
            LOGGER.info('Removed file: %r', path)
        except OSError as ex:
            LOGGER.error('Failed to remove file %r: %s', path, ex)

    def _rename_file(src, dst):
        try:
            os.rename(src, dst)
            LOGGER.info('Renamed file from %r to %r', src, dst)
        except OSError as ex:
            LOGGER.error('Failed to rename file from %r to %r: %s', src, dst, ex)

    def _copy_file(src, dst):
        try:
            shutil.copy2(src, dst)
            LOGGER.info('Copied file from %r to %r', src, dst)
        except OSError as ex:
            LOGGER.error('Failed to copy file from %r to %r: %s', src, dst, ex)

    def _create_sparse_file(path, size):
        try:
            with open(path, 'wb') as f:
                f.truncate(size)
            LOGGER.info('Created sparse file: %r', path)
        except OSError as ex:
            LOGGER.error('Failed to create sparse file %r: %s', path, ex)

    def _resize_file(path, size):
        try:
            with open(path, 'r+b') as f:
                f.truncate(size)
            LOGGER.info('Resized file: %r', path)
        except OSError as ex:
            LOGGER.error('Failed to resize file %r: %s', path, ex)

    def _update_loopdev_sizes(img):
        try:
            realpath = os.path.realpath(img)
            for loopdev in glob.glob('/sys/block/loop*/loop/backing_file'):
                with open(loopdev, 'r') as f:
                    if realpath == f.read().strip():
                        dev = '/dev/' + os.path.basename(os.path.dirname(loopdev))
                        with open(dev, 'r+b') as dev_f:
                            fcntl.ioctl(dev_f.fileno(), LOOP_SET_CAPACITY)
            LOGGER.info('Updated loop device sizes for image: %r', img)
        except Exception as ex:
            LOGGER.error('Failed to update loop device sizes for image %r: %s', img, ex)

    def _attempt_ficlone(src_io, dst_io):
        try:
            fcntl.ioctl(dst_io.fileno(), FICLONE, src_io.fileno())
            LOGGER.info('Reflinked file from %r to %r', src_io.name, dst_io.name)
            return True
        except OSError as ex:
            if ex.errno in (errno.EBADF, errno.EINVAL, errno.EOPNOTSUPP, errno.EXDEV):
                LOGGER.info('Reflink not supported, falling back to copy for %r to %r', src_io.name, dst_io.name)
                return False
            else:
                LOGGER.error('Error attempting to reflink file from %r to %r: %s', src_io.name, dst_io.name, ex)
                raise

