public boolean addValue(String text, int score) {
        if (scores.size() >= max_to_keep) {
            int minScore = Integer.MAX_VALUE;
            int minIndex = -1;
            for (int i = 0; i < scores.size(); i++) {
                if (scores.get(i) < minScore) {
                    minScore = scores.get(i);
                    minIndex = i;
                }
            }
            if (score > minScore) {
                strings.remove(minIndex);
                scores.remove(minIndex);
            } else {
                return false;
            }
        }
        strings.add(text);
        scores.add(score);
        return true;
    }

