// Define the Promise constructor and prototype methods
    var Promise = function(executor) {
        if (!(this instanceof Promise)) {
            throw new TypeError('Promise constructor must be called with "new"');
        }
        if (typeof executor !== 'function') {
            throw new TypeError('Promise constructor\'s argument is not a function');
        }

        this._state = 'pending'; // 'pending', 'fulfilled', or 'rejected'
        this._value = null; // value for fulfilled, reason for rejected
        this._handlers = []; // handlers for then/catch

        try {
            executor(this._resolve.bind(this), this._reject.bind(this));
        } catch (err) {
            this._reject(err);
        }
    };

    Promise.prototype._resolve = function(value) {
        if (this._state !== 'pending') return;
        this._state = 'fulfilled';
        this._value = value;
        this._handlers.forEach(handler => this._handle(handler));
        this._handlers = null;
    };

    Promise.prototype._reject = function(reason) {
        if (this._state !== 'pending') return;
        this._state = 'rejected';
        this._value = reason;
        this._handlers.forEach(handler => this._handle(handler));
        this._handlers = null;
    };

    Promise.prototype._handle = function(handler) {
        if (this._state === 'pending') {
            this._handlers.push(handler);
        } else {
            if (this._state === 'fulfilled' && typeof handler.onFulfilled === 'function') {
                handler.onFulfilled(this._value);
            }
            if (this._state === 'rejected' && typeof handler.onRejected === 'function') {
                handler.onRejected(this._value);
            }
        }
    };

    Promise.prototype.then = function(onFulfilled, onRejected) {
        return new Promise((resolve, reject) => {
            this._handle({
                onFulfilled: value => {
                    if (typeof onFulfilled === 'function') {
                        try {
                            resolve(onFulfilled(value));
                        } catch (err) {
                            reject(err);
                        }
                    } else {
                        resolve(value);
                    }
                },
                onRejected: reason => {
                    if (typeof onRejected === 'function') {
                        try {
                            resolve(onRejected(reason));
                        } catch (err) {
                            reject(err);
                        }
                    } else {
                        reject(reason);
                    }
                }
            });
        });
    };

    Promise.prototype.catch = function(onRejected) {
        return this.then(null, onRejected);
    };

    // Static methods
    Promise.resolve = function(value) {
        if (value instanceof Promise) {
            return value;
        }
        return new Promise(resolve => resolve(value));
    };

    Promise.reject = function(reason) {
        return new Promise((_, reject) => reject(reason));
    };

    Promise.all = function(promises) {
        return new Promise((resolve, reject) => {
            let results = [];
            let remaining = promises.length;
            if (remaining === 0) resolve(results);
            promises.forEach((promise, index) => {
                Promise.resolve(promise).then(value => {
                    results[index] = value;
                    if (--remaining === 0) {
                        resolve(results);
                    }
                }, reject);
            });
        });
    };

    Promise.race = function(promises) {
        return new Promise((resolve, reject) => {
            promises.forEach(promise => {
                Promise.resolve(promise).then(resolve, reject);
            });
        });
    };

